Due to the fact that .transfer() and .send() forward exactly 2,300 gas to 
the recipient. This hardcoded gas stipend aimed to prevent reentrancy 
vulnerabilities, but this only makes sense under the assumption that gas 
costs are constant. Recently EIP 1884 was included in the Istanbul hard 
fork. One of the changes included in EIP 1884 is an increase to the gas 
cost of the SLOAD operation, causing a contract's fallback function to 
cost more than 2300 gas.
// bad 
contract Vulnerable { 
    function withdraw(uint256 amount) external { 
        // This forwards 2300 gas, which may not be enough if the recipient 
        // is a contract and gas costs change. 
        msg.sender.transfer(amount); 
    } 
}

// good 
contract Fixed { 
    function withdraw(uint256 amount) external { 
        // This forwards all available gas. Be sure to check the return value! 
        (bool success, ) = msg.sender.call{value:amount}(""); 
        require(success, "Transfer failed."); 
    } 
}

